body_md:
Hierarchical games are a useful model template for computational approaches to competitive mechanism design and certain dynamic games. The key goal of mechanism design is to implement a desired Nash equilibrium in a population of agents. Hence, the designers need to anticipate the equilibrium conditions of the lower level problem. For concreteness, we consider the situation in which two upper level players manage the strategies of $N$ lower-level players. The lower level players engage in a Nash game, characterized by local minimisation problems 
$$
 \min_{y^{
u}\in\mathcal{Y}^{
u}}\{h^{\ell}_{
u}(y^{
u},y^{-
u})+\varphi^{\ell}_{
u}(y^{
u})\}.
$$
Under standard differentiability and monotonicity assumptions on the data of the game, we can characterize equilibria of this lower level game in terms the variational inequality $\mathcal{S}_{2}=\operatorname{zer}({\mathsf{F}}_{2}+\partial g_{2})$, where ${\mathsf{F}}_{2}(y)=(
abla_{y^{1}}h^{\ell}_{1}(y),\ldots,
abla_{y^{N}}h^{\ell}_{N}(y))$. The problem of the upper level players is to select a Nash equilibrium in the lower level game by itself being engaged in a strategic optimisation problem of the form 
$$
\min_{x^{\mu}\in\mathcal{X}^{mu}}\{h^{u}_{\mu}(x^{\mu},x^{-\mu})+\varphi^{u}_{\mu}(x^{\mu})\}\quad 	ext{s.t.: }(x^{\mu},x^{-\mu})\in\mathcal{S}_{2},\mu\in\{1,2\}. 
$$
The strategy $x^{\mu}=(y^{
u})_{
u\in\mathcal{N}_{\mu}}$ consists of the actions of the adjunct lower level players. Writing the equilibrium conditions for the resulting hierarchical games leads to the problem formulation \eqref{eq:P}.

\label{ass:standing} 
The following hypothesis are assumed to hold throughout the paper:
\begin{itemize}
\item[(i)] The solution set $\mathcal{S}_{1}$ of \eqref{eq:P} is nonempty. In particular, $\mathcal{S}_{2}\triangleq \operatorname{zer}({\mathsf{F}}_{2}+\partial g_{2})\neq\varnothing$.
\item[(ii)] The functions $g_{i}:\mathcal{X}\to(-\infty,\infty], i=1,2$ are proper convex and lower semi-continuous.
\item[(iii)] The operators ${\mathsf{F}}_{i},i=1,2,$ are monotone and $L_{{\mathsf{F}}_{i}}$-Lipschtiz.
\item[(iv)] The operators ${\mathsf{F}}_{i}$ admit a finite sum representation ${\mathsf{F}}_{i}=\sum_{\mathtt{a}\in\mathcal{A}}{\mathsf{F}}_{i}^{\mathtt{a}}$, where $\mathcal{A}$ is a finite index set, and ${\mathsf{F}}_{i}^{\mathtt{a}}:\mathcal{X}\to\mathcal{X}$ are given mappings.
\end{itemize}

\label{ass:BVg}
The set $\operatorname{dom}(g_1)\cap \operatorname{dom}(g_2)$ is closed, and for any compact sets $\mathcal{B},\mathcal{C}\subset\mathcal{Z}$ satisfying $\mathcal{B},\mathcal{C} \subset\operatorname{dom}(g_{1})\cap\operatorname{dom}(g_{2})$,                                   
we have $\operatorname{\mathsf{Var}}(g_{1}\vert \mathcal{B}\times\mathcal{C})<\infty$.

\label{ass:Oracle}
For all $k\in\varmathbb{N}$, the operator ${\mathsf{V}}_{k}$ admits a stochastic oracle ${\mathsf{V}}^{\xi}_{k}$ such that $\varmathbb{E}[{\mathsf{V}}_{k}^{\xi}(x)]={\mathsf{V}}_{k}(x)$ for all $x\in\mathcal{X}$. There exists $\mathcal{L}_{k}>0$ such that $\sup_{k\geq 0}\mathcal{L}_{k}\leq L_{1}$ and 
    \begin{equation}\label{eq:LipV}
    \varmathbb{E} \left[\, \norm{{\mathsf{V}}^{\xi}_k(x) - {\mathsf{V}}
    _k^{\xi}(y)}\right] \leq \mathcal{L}_k  \norm{x-y}\qquad \forall x,y \in \mathcal{X}.
    \end{equation}

\label{ex:sampling_prob}
Working in a finite sum setting, we can construct different stochastic oracles. Since ${\mathsf{V}}_{k}=\sum_{\mathtt{a}\in\mathcal{A}}{\mathsf{V}}^{\mathtt{a}}_{k}$, if each ${\mathsf{V}}^{\mathtt{a}}_{k}$ is $L_{k,\mathtt{a}}$-Lipschitz, then the triangle inequality gives $L_{{\mathsf{V}}_{k}}\leq\sum_{\mathtt{a}\in\mathcal{A}}L_{k,\mathtt{a}}$. The two simplest stochastic oracles can be defined as follows: 
\begin{enumerate}
    \item ${\mathsf{V}}^{\mathtt{a}}_{k}(x)=\abs{\mathcal{A}}{\mathsf{V}}^{\mathtt{a}}_{k}(x)$ and $\xi:\Omega\to\mathcal{A}$ is the uniformly distributed random variable with law $Q_{\mathtt{a}}\triangleq\varmathbb{P}(\xi=\mathtt{a})=\frac{1}{\abs{\mathcal{A}}}$. In this case $\mathcal{L}_{k}=\sqrt{\abs{\mathcal{A}}\sum_{\mathtt{a}\in\mathcal{A}}L_{k,a}^{2}}$. Since $\beta_{k}\leq \beta_{1}$, we can take as upper bound on the Lipschitz modulus $L_{1}=\mathcal{L}_{1}$.
    \item Let $\xi:\Omega\to\mathcal{A}$ be the random variable with law $Q_{\mathtt{a}}\triangleq\varmathbb{P}(\xi=\mathtt{a})=\frac{L_{1,\mathtt{a}}}{\sum_{\mathtt{a}\in\mathcal{A}}L_{1,\mathtt{a}}}$. Set ${\mathsf{V}}^{\xi}_{k}(x)=\frac{1}{q_{a}}{\mathsf{V}}^{\mathtt{a}}_{k}$ on the event $\{\xi=\mathtt{a}\}$. In this case, we have $\mathcal{L}_{k}=\sum_{\mathtt{a}\in\mathcal{A}}L_{1,\mathtt{a}}=L_{1}.$ 
\end{enumerate}

The feasibility gap and optimality gap for \eqref{eq:P} are defined as 
\begin{align}
&\Theta_{\rm Feas}(x\vert\mathcal{C})=\sup_{y\in\mathcal{C}} H^{({\mathsf{F}}_{2},g_{2})}(x,y) \qquad \text{ and } \qquad \Theta_{\rm Opt}(x\vert\mathcal{C}\cap\mathcal{S}_{2})=\sup_{y\in\mathcal{C}\cap\mathcal{S}_{2}} H^{({\mathsf{F}}_{1},g_{1})}(x,y).\label{eq:Opt}
\end{align}

\label{def:WSMain}
Let $\mathcal{S}$ be the solution set of $\operatorname{HVI}({\mathsf{F}},g)$. We say $\mathcal{S}$ is $(\kappa,\rho)$-weak sharp with $\kappa>0$ and $\rho\in(1,2)$ if
\begin{equation}\label{eq:WSDef}
(\forall z^{\ast}\in\mathcal{S})(\forall z\in\operatorname{dom}(g)):\quad H^{({\mathsf{F}},g)}(z,z^{\ast})\geq\kappa\rho^{-1}\operatorname{dist}(z,\mathcal{S})^{\rho}.
\end{equation}

\label{lem:LB}
Consider problem \eqref{eq:P}. Let Assumption \ref{ass:standing} and \ref{ass:CQ} hold. Let $\mathcal{U}_1\subseteq\operatorname{dom}(g_{1})$ be a nonempty compact set with $\mathcal{U}_1\cap\mathcal{S}_{1}\neq\varnothing$. Then, there exists a constant $B_{\mathcal{U}_1}>0$ such that
\begin{equation}\label{eq:LB1}
\Theta_{\rm Opt}(x\vert\mathcal{U}_1\cap\mathcal{S}_1)\geq-B_{\mathcal{U}_1}\operatorname{dist}(x,\mathcal{S}_{2}) \quad\forall x\in\mathcal{X}.
\end{equation}
Suppose $\mathcal{S}_{2}$ is $(\kappa,\rho)$-weakly sharp. Then for all nonempty and compact subsets $\mathcal{U}_2\subseteq\operatorname{dom}(g_{2})$ with $\mathcal{U}_{2}\cap\mathcal{S}_{2}\neq\varnothing$, and all $x\in\operatorname{dom}(g_{2})$, we have 
\begin{equation}\label{eq:WS}
\operatorname{dist}(x,\mathcal{S}_{2})\leq\left[\rho\kappa^{-1}\Theta_{\rm Feas}(x\vert \mathcal{U}_2\cap \mathcal{S}_2)\right]^{1/\rho}.
\end{equation}

\label{ass:ACcondition}[Attouch-Czarnecki condition]
The step size sequence $(\tau_{k})_{k\geq 0}$ and the regularization sequence $(\beta_{k})_{k\geq 0}$ satisfy
\begin{equation}\label{eq:AttCza}
(\forall p\in\textnormal{Range}(\operatorname{\mathsf{NC}}_{\mathcal{S}_{2}})):\;\sum_{k=1}^{\infty}\tau_{k}\left[\sup_{z\in\mathcal{S}_{2}}\varphi^{({\mathsf{F}}_{2},g_{2})}(z,\beta_{k}p)-\operatorname{\mathtt{s}}(\beta_{k}p\vert\mathcal{S}_{2})\right]<\infty.
\end{equation}

\label{rem:Tikhonov}
Assumption \ref{ass:ACcondition} looks quite daunting to verify, but as already observed in \cite{boct2025accelerating}, it fits very natural to the geometric setting of this paper. Indeed, let us assume that $\mathcal{S}_{2}$ is $(\kappa,\rho)$-weakly sharp, with $\kappa>0$ and $\rho\in(1,2)$. According to Definition \ref{def:WSMain}, for all $x\in\operatorname{dom}(g_{2})$ and for all $x^{*}\in\mathcal{S}_{2}$, we have $H^{({\mathsf{F}}_{2},g_{2})}(x,x^{*})\geq \frac{\kappa}{\rho}\operatorname{dist}(x,\mathcal{S}_{2})^{\rho}$. Hence, eq. \eqref{eq:dualphimaintext} yields for all $x\in\mathcal{S}_{2}$
\begin{align*}
\varphi^{({\mathsf{F}}_{2},g_{2})}(x,\beta_{k}p^{\ast})-\operatorname{\mathtt{s}}(\beta_{k}p^{\ast}\vert\mathcal{S}_{2})&\leq \left(H^{({\mathsf{F}}_{2},g_{2})}(\bullet,x)\right)^{\ast}(\beta_{k}p^{\ast})-\operatorname{\mathtt{s}}(\beta_{k}p^{\ast}\vert\mathcal{S}_{2})\leq \kappa^{-\frac{1}{\rho-1}}\left(\frac{\rho-1}{\rho}\right)\beta_{k}^{\frac{\rho}{\rho-1}}\norm{p^{\ast}}^{\frac{\rho}{\rho-1}}. 
\end{align*}
This shows that under the $(\kappa,\rho)$-weak sharpness condition, the summability condition \eqref{eq:AttCza} is satisfied whenever $\sum_{k\geq 1}\tau_{k}\beta^{\frac{\rho}{\rho-1}}_{k}<\infty.$ 
\hfill{\footnotesize$\Diamond$}

\label{lem:energy}
Let Assumptions \ref{ass:standing}- \ref{ass:Oracle} hold. Given $\alpha\in(0,1],\theta\in (0,1]$ and $\tau_{k}\leq \frac{\sqrt{1-\alpha}}{\mathcal{L}_{k}}\gamma$, for $\gamma\in(0,1)$. For any $x\in\operatorname{dom}(g_{1})\cap\operatorname{dom}(g_{2})$, the iterates produced by Algorithm \ref{alg:Euclid} satisfy 
\begin{equation}\label{eq:Energy2}
\begin{split}
\varmathbb{E}[\mathcal{E}_{k+1}(x)\vert\mathcal{H}_{k}]+2\tau_{k}\Psi_{k}(x)&\leq \mathcal{E}_{k}(x)-\alpha\norm{y_{k+1}-x_{k}}^{2}\\ 
&-(1-\gamma)\left[(1-\alpha)\norm{y_{k+1}-w_{k}}^{2}+\varmathbb{E}\left(\norm{x_{k+1}-y_{k+1}}^{2}\vert\mathcal{H}_{k}\right)\right].
\end{split}
\end{equation}

\label{lem:boundsequence}
Let Assumptions \ref{ass:standing}- \ref{ass:ACcondition} hold. Let $x^{*}\in\mathcal{S}_{1}$ be arbitrary. Then, under the same conditions as in Lemma \ref{lem:energy}, the following statements hold true:
\begin{itemize}
\item[(i)] $\lim_{k\to\infty}\mathcal{E}_{k}(x^{*})$  exists $\varmathbb{P}$-a.s.
\item[(ii)] $\lim_{k\to\infty}\norm{y_{k+1}-w_{k}}^{2}=\lim_{k\to\infty}\norm{y_{k+1}-x_{k+1}}^{2}=0$ $\varmathbb{P}$-a.s. 
\end{itemize}
In particular, the processes $(x_{k})_{k},(w_{k})_{k}$ and $(y_{k})_{k}$ are almost surely bounded, and 
\begin{equation}\label{eq:aux1}
    \sum_{k=0}^{\infty}\left((1-\alpha)\varmathbb{E}\left[\norm{y_{k+1}-w_{k}}^{2}\right]+\varmathbb{E}\left[\norm{x_{k+1}-y_{k+1}}^{2}\right]\right)\leq\frac{1}{1-\gamma}\left(\mathcal{E}_{0}(x^{*})+2\sum_{k=0}^{\infty}\tau_{k}h_{k}\right),
\end{equation}
where $h_{k}\triangleq \sup_{x\in\mathcal{S}_{2}}\varphi^{({\mathsf{F}}_{2},g_{2})}(x,\beta_{k}p^{*})-\operatorname{\mathtt{s}}(\beta_{k}p^{*}\vert\mathcal{S}_{2})$ with a certain $p^\ast \in \operatorname{\mathsf{NC}}_{\mathcal{S}_{2}}(x^\ast)$.

\label{th:mainMonotone}
    Let Assumptions \ref{ass:standing}-\ref{ass:ACcondition} hold. Given $\theta\in(0,1],\alpha=1-\theta$, and $\tau_{k}\leq \frac{\sqrt{\theta}}{\mathcal{L}_{k}}\gamma$ for $\gamma\in(0,1)$. Let $\mathcal{U}_1, \mathcal{U}_2$ as in Lemma \ref{lem:LB}, let $x^\ast \in \mathcal{S}_1$, and define $p^\ast, h_k$ as in Lemma \ref{lem:boundsequence}. Further, define
$\bar{y}^{K}\triangleq \frac{\sum_{k=0}^{K-1}\tau_{k}y_{k+1}}{T_{k}}$ and $T_{K}\triangleq \sum_{k=0}^{K-1}\tau_{k}$. 
Then, there are constants $C_{\mathcal{U}_1}, C_{\mathcal{U}_2}, B_{\mathcal{U}_1} > 0$ such that we have                                                                                                                                                                    
\begin{equation}\label{eqthm:feas}
        \begin{aligned}
          \varmathbb{E}[\Theta_{\rm Feas}(\bar{y}^{K}\vert\mathcal{U}_{2})]&\leq \frac{7}{4T_{K}}\max_{x\in\mathcal{U}_{2}}\norm{x-x_{0}}^{2}+\frac{7}{2T_{K}(1-\gamma)}\sum_{k=0}^{\infty}\tau_{k}h_{k}\\
          &+C_{\mathcal{U}_{2}}\frac{\sum_{k=0}^{K-1}\tau_{k}\beta_{k}}{T_{K}}+\frac{7}{2T_{K}(1-\gamma)}\norm{x^{*}-x_{0}}^{2}\triangleq W_{\rm Feas}(K,x_{0},,x^{*},\mathcal{U}_{2}),


\end{aligned}
\end{equation}

\begin{equation}\label{eqthm:opt}
    \begin{aligned}
    -B_{\mathcal{U}_1}\operatorname{dist}(\bar{y}^{K},\mathcal{S}_{2})&\leq \varmathbb{E} \left[\Theta_{\rm Opt}(\bar{y}^{K}\vert\mathcal{U}_1\cap\mathcal{S}_{2})\right] \\
    &\quad 
    \leq  \frac{C_{\mathcal{U}_1}}{2T_K \beta_K}+\frac{3}{4T_{K}}\max_{x\in \mathcal{U}_1 \cap \mathcal{S}_2} \norm{x-x_0}^2+\frac{7}{2(1-\gamma)T_{K}\beta^{2}_{K}}\norm{x^{*}-x_{0}}^{2}\\
    &+\frac{7}{2(1-\gamma)T_{K}\beta^{2}_{K}}\sum_{k=0}^{\infty}\tau_{k}h_{k}\triangleq W_{\rm Opt}(K,x_{0},x^{*},\mathcal{U}_{1}).

    \end{aligned}
\end{equation}
 If the lower level solution set $\mathcal{S}_{2}$ is $(\kappa,\rho)$-weakly sharp, then we also have the lower bound 
\begin{equation}\label{eqthm:optweaklysharp}

        -B_{\mathcal{U}_{1}}\left[\frac{\rho}{\kappa}W_{\rm Feas}(K,x_{0},\mathcal{U}_{2})\right]^{1/\rho}\leq \varmathbb{E} \left[\Theta_{\rm Opt}(\bar{y}^{K}\vert\mathcal{U}_1\cap\mathcal{S}_{2})\right]
\end{equation}

\label{prop:ratesEucliddelta}
Assume that $\mathcal{S}_{2}$ is $(\kappa,\rho)$-weakly sharp. Let Algorithm \ref{alg:Euclid} use constant step size $\tau_{k}=\bar{\tau}\leq \frac{\sqrt{\theta}\gamma}{L_{1}}$ and regularization sequence $(\beta_{k})_{k\geq 0}$ of the form \eqref{eq:betapower} with $a,b>0$ and $\delta>1-1/\rho=\frac{1}{\rho^{*}}$. Then, we have 
\begin{equation}
W_{\rm Feas}(K,x_{0},x^{*},\mathcal{U}_{2})\leq O((K+b)^{-\delta}), \quad \text{ and } \quad W_{\rm Opt}(K,x_{0},x^{*},\mathcal{U}_{1})\leq O((K+b)^{-(1-2\delta)}). 
\end{equation}

\label{lem:bounded_Bregman}
Let Assumptions \ref{ass:standing}-\ref{ass:CQ} and \ref{ass:Oracle_Bregman} hold. Consider Algorithm \ref{alg:MirrorProx}, run with $\tau_{s}\leq \frac{\sqrt{1-\alpha}}{2L_{s}}.$ Let $x^\ast \in \mathcal{S}_1$ with corresponding $p^\ast \in \operatorname{\mathsf{NC}}_{\mathcal{S}_{2}}(x^\ast)$ and assume that $\sum_{s=0}^{\infty} \tau_{s}h(\beta_{s}p^{*})<\infty$. Then 
\begin{enumerate} [label=(\roman*)]
    \item $\lim_{s\to\infty}\mathcal{E}^{s}(x^{*})$ exists $\varmathbb{P}$-a.s. for all $x^{*}\in\mathcal{S}_{1}.$ 
    \item $\sum_{s=0}^{\infty}\sum_{k=0}^{K-1}\norm{y^{s}_{k+1}-w^{s}}^2<\infty$ and $\sum_{s=0}^{\infty}\sum_{k=0}^{K-1}\norm{x^{s}_{k+1}-y^{s}_{k+1}}^{2}<\infty$ $\varmathbb{P}$-a.s.
    \item \label{eq:sum_iterates_Bregman}
    $\displaystyle
    \sum_{s=0}^{S-1}\sum_{k=0}^{K-1}
    \Big((1-\alpha)\varmathbb{E}[\norm{y^{s}_{k+1}-w^{s}}^{2}]
    + \varmathbb{E}[\norm{x^{s}_{k+1}-y^{s}_{k+1}}^{2}]\Big)
    \leq
    4\mathcal{E}^{0}(x^{*})+4K\sum_{s=0}^{S-1}\tau_{s}h(\beta_{s}p^{*}).$
\end{enumerate}

Let conditions of Lemma \ref{lem:bounded_Bregman} hold, $\mathcal{U}_1, \mathcal{U}_2$ be subsets, chosen as in Lemma \ref{lem:LB}. Fix $x^{*}\in\mathcal{S}_{1}$ and corresponding $p^{*}\in\operatorname{\mathsf{NC}}_{\mathcal{S}_{2}}(x^{*})$. Set 
$T_S \triangleq \sum_{s=0}^{S-1} \tau_s, \, \hat{x}^S \triangleq \frac{1}{K T_S} \sum_{s=0}^{S-1} \tau_s \sum_{k=0}^{K-1} y_{k+1}^s$, 
$R^2(x^{*},x_0^0)\triangleq\sup_{x \in \mathcal{U}_2}\mathcal{E}^{0}(x)+\sup_{x \in \mathcal{U}_2}D(x,x_0^0)+\mathcal{E}^{0}(x^{*})$.

Then, there are constants $C_{\mathcal{U}_1}, C_{\mathcal{U}_2}, B_{\mathcal{U}_1} > 0$ s.t.
\begin{align}
\label{eq:Bregman_theta_feas}
     \varmathbb{E}[\Theta_{\rm Feas}(\hat{x}^S\vert\mathcal{U}_{2})]&\leq \frac{R^2(x^{*},x_0^0)}{KT_{S}}+\frac{\sum_{s=0}^{S-1}\tau_sh(\beta_{s}p^{*})}{2T_{S}}+\frac{\sum_{s=0}^{S-1}\beta_{s}\tau_{s}}{T_{S}}C_{\mathcal{U}_{2}}\triangleq W^B_{\rm Feas}(K,S,x_{0}^0,x^{*},\mathcal{U}_{2})


\\
-B_{\mathcal{U}_1}\operatorname{dist}(\hat{x}^S,\mathcal{S}_{2})& \leq \varmathbb{E}[\Theta_{\rm Opt}(\hat{x}^S\vert\mathcal{U}_{1}\cap \mathcal{S}_2)] \leq\frac{C_{\mathcal{U}_1}}{\beta_SK T_S} + \frac{\sup_{x \in \mathcal{U}_{1}\cap \mathcal{S}_2} D(x,x_0^0)}{K T_S}+  \frac{ \mathcal{E}^{0}(x^{*})}{2 K\beta_S^2 T_S} \nonumber \\ 
     & \hspace{10em}+\frac{\sum_{s=0}^{S-1}\tau_{s}h(\beta_{s}p^{*})}{2 \beta_S^2 T_S} \triangleq W^B_{\rm Opt}(K,S,x_{0}^0,x^{*},\mathcal{U}_{1}) \label{eq:Bregman_theta_opt}. 
\end{align}












 If the lower level solution set $\mathcal{S}_{2}$ is $(\kappa,\rho)$-weakly sharp, then we also have the lower bound 
\begin{equation}\label{eqthm:optweaklysharp}
        -B_{\mathcal{U}_{1}}\left[\rho\kappa^{-1}W^B_{\rm Feas}(K,S,x_{0}^0,x^{*},\mathcal{U}_{2})\right]^{1/\rho}\leq \varmathbb{E} \left[\Theta_{\rm Opt}(\hat{x}^S\vert\mathcal{U}_1\cap\mathcal{S}_{2})\right].
\end{equation}

\label{lem:RS}
Let ${\varmathbb{F}}=(\mathcal{F}_{k})_{k\in\varmathbb{N}}$ be a filtration. Let $(\mathcal{E}_{k})_{k}\in\ell_{+}({\varmathbb{F}}),(\gamma_{k})_{k}\in\ell^{1}_{+}({\varmathbb{F}}),(D_{k})_{k}\in\ell_{+}({\varmathbb{F}})$ and $(\eta_{k})_{k}\in\ell^{1}_{+}({\varmathbb{F}})$ be such that 
$$
\varmathbb{E}(\mathcal{E}_{k+1}\vert\mathcal{F}_{k})+D_{k}\leq(1+\gamma_{k})\mathcal{E}_{k}+\eta_{k}\quad\forall k\in\varmathbb{N},\varmathbb{P}-\text{a.s.} 
$$
Then $(D_{k})_{k\in\varmathbb{N}}\in\ell^{1}_{+}({\varmathbb{F}})$ and $(\mathcal{E}_{k})_{k\in\varmathbb{N}}$ converges $\varmathbb{P}$-a.s. to a $[0,\infty)$-valued random variable.

\label{lem:3point}
   Let $\mathsf{d}$ be a distance generating function, inducing the Bregman divergence $D$. We have
    \begin{equation}
       \begin{aligned}
            \inner{\nabla \mathsf{d}(x) - \nabla \mathsf{d}(y),z-x} = D(z,y) - D(z,x) - D(x,y)\quad \forall x,y,z \in \mathcal{X}
       \end{aligned}
    \end{equation}

\label{lem:bregmanproxineq}
    Let $ g$ be a proper convex and lower semi-continuous function and 
    \begin{align*}
        x^+ = \operatorname*{argmin}_z \left\{g(z) + \inner{v,z} + \alpha D(z,x_1)+ (1-\alpha) D(z,x_2)\right\}.
    \end{align*}
    Then for any $ x \in \mathcal{X}$ the following inequality holds:  
    \begin{align*}
        g(x) - g(x^+) + \inner{v,x-x^+} \geq &\ D(x,x^+) + \alpha (D(x^+,x_1) - D(x,x_1))\\
        &\quad+(1-\alpha)(D(x^+,x_2) + (1-\alpha)D(x,x_2))
    \end{align*}

By the optimality condition we have for $ x^+$
    \begin{align*}
        0 \in \partial g(x^+) + v + \alpha (\nabla \mathsf{d}(x^+) - \nabla \mathsf{d}(x_1)) + (1-\alpha) (\nabla \mathsf{d}(x^+) - \nabla \mathsf{d}(x_2)).
    \end{align*}
By the subgradient inequality for $ g$, we get
\begin{align*}
    g(x) - g(x^+) \geq \inner{v + \alpha(\nabla \mathsf{d}(x^+) - \nabla \mathsf{d}(x_1)) + (1-\alpha)(\nabla \mathsf{d}(x^+) - \nabla \mathsf{d}(x_2)), x^+ - x}.
\end{align*}
The result follows then from applying the three point identity Lemma \ref{lem:3point} twice to the gradient terms.

\label{def:WS}
Let $\mathcal{S}$ be the nonempty solution set of $\operatorname{HVI}({\mathsf{F}},g)$. We say $\mathcal{S}$ is $(\kappa,\rho)$-weak sharp with $\kappa>0$ and $\rho\geq 1$ if
\begin{equation}\label{eq:WSDefAppendix}
(\forall z^{\ast}\in\mathcal{S})(\forall z\in \operatorname{dom}(g)):\quad H^{({\mathsf{F}},g)}(z,z^{\ast})\geq\kappa\rho^{-1}\operatorname{dist}(z,\mathcal{S})^{\rho}.
\end{equation}

Consider problem \eqref{eq:P}. Let Assumption \ref{ass:standing} and \ref{ass:CQ} hold. Let $\mathcal{U}_1\subseteq\operatorname{dom}(g_{1})$ be a nonempty compact set with $\mathcal{U}_1\cap\mathcal{S}_{1}\neq\varnothing$. Then, there exists a constant $B_{\mathcal{U}_1}>0$ such that
\begin{equation}\label{eq:LB1Appendix}
\Theta_{\rm Opt}(z\vert\mathcal{U}_1\cap\mathcal{S}_1)\geq-B_{\mathcal{U}_1}\operatorname{dist}(x,\mathcal{S}_{2}), \quad\forall x\in\mathcal{X}.
\end{equation}
Suppose $\mathcal{S}_{2}$ is $(\kappa,\rho)$-weakly sharp. Then for all nonempty and compact subsets $\mathcal{U}_2\subseteq\operatorname{dom}(g_{2})$ with $\mathcal{U}_{2}\cap\mathcal{S}_{2}$ and all $x\in\operatorname{dom}(g_{2})$, we have 
\begin{equation}\label{eq:WSAppendix}
\operatorname{dist}(z,\mathcal{S}_{2})\leq\left[\frac{\rho}{\kappa}\Theta_{\rm Feas}(x\vert \mathcal{U}_2\cap \mathcal{S}_2)\right]^{1/\rho}.
\end{equation}

Let $x^{*}\in\mathcal{S}_{1}=\operatorname{zer}({\mathsf{F}}_{1}+\partial g_{1}+\operatorname{\mathsf{NC}}_{\mathcal{S}_{2}})\subset\mathcal{S}_{2}$. Then, there exists $p^{*}\in\operatorname{\mathsf{NC}}_{\mathcal{S}_{2}}(x^{*})$ such that $-{\mathsf{F}}_{1}(x^{*})-p^{*}\in\partial g_{1}(x^{*})$. By the convex sugradient inequality, this implies 
\begin{equation}\label{eq:b1}
\inner{{\mathsf{F}}_{1}(z^{*}),x-x^{*}}+g_{1}(x)-g_{1}(x^{*})\geq \inner{-p^{*},x-x^{*}}\qquad\forall x\in\mathcal{X}.
\end{equation}
Take $x\in \mathcal{X}$ and let $\hat{x}=\Pi_{\mathcal{S}_{2}}(x)$ be the orthogonal projector of $x$ onto $\mathcal{S}_{2}$. Thus, $\inner{p^{*},\hat{x}-x^*}\leq 0$, resulting in
\begin{equation*}
\inner{p^{*},\hat{x}-x}\leq\inner{p^{*},x^{*}-x}, 
\end{equation*}
which implies when combined with \eqref{eq:b1} 
\begin{align*}
\inner{{\mathsf{F}}_{1}(x^{*}),x-x^{*}}+&g_{1}(x)-g_{1}(x^{*})\geq \inner{p^{*},\hat{x}-x}\geq -\norm{p^{*}}\cdot\norm{\hat{x}-x}=-\norm{p^{*}}\operatorname{dist}(x,\mathcal{S}_{2}).
\end{align*}
Hence, for all compact $\mathcal{U}_1\subset\operatorname{dom}(g_{1})$ with $x^*\in\mathcal{U}_1\cap\mathcal{S}_{1}\neq\varnothing$, we conclude 
$\Theta_{\rm Opt}(x\vert\mathcal{U}_1\cap\mathcal{S}_1)\geq-B_{\mathcal{U}_1}\operatorname{dist}(x,\mathcal{S}_{2})$, where $B_{\mathcal{U}_1}=\norm{p^{*}}$. 

To show \eqref{eq:WSAppendix}, we can directly use Definition \ref{def:WS}, to conclude
\begin{align*}
\Theta_{\rm Feas}(x\vert\mathcal{U}_2\cap\mathcal{S}_2)=\sup_{x^{*}\in\mathcal{U}_2\cap\mathcal{S}_2}H^{({\mathsf{F}}_{2},g_{2})}(x,x^{*})\geq \frac{\kappa}{\rho}\operatorname{dist}(x,\mathcal{S}_{2})^{\rho}.
\end{align*}
